DONE = {173: "No open questions left.", 174: "A working demo or its backup.", 175: "Paperwork complete and travel ready.", 176: "Ready for fair day."}

TITLES = {172: 'Contingency 1: fix the biggest open problem', 173: 'Contingency 2: close any unanswered judge question', 174: 'Contingency 3: demo safety check', 175: 'Contingency 4: paperwork and travel', 176: 'Contingency 5: final kit check, then rest'}

def apply():
    for n, t in TITLES.items():
        HOURS[n - 1]['title'] = t
    for n, steps in EXTRA.items():
        h = HOURS[n - 1]
        h["steps"] = [s for s in h["steps"] if s != "Same as above."] + steps
    for n, c in CHECKS.items():
        HOURS[n - 1]["checks"] = c
    for n, d in DONE.items():
        HOURS[n - 1]["done"] = d
